database.kode_skema:
import { pgTable, uuid, text, integer, boolean, timestamp, pgEnum } from "drizzle-orm/pg-core";

export const peranEnum = pgEnum("peran", ["pemilik_salon"]);
export const statusBookingEnum = pgEnum("status_booking", ["dikonfirmasi", "selesai", "batal"]);
export const statusKirimEnum = pgEnum("status_kirim", ["berhasil", "gagal"]);

export const pengguna = pgTable("pengguna", {
  id: uuid("id").primaryKey().defaultRandom(),
  nama: text("nama").notNull(),
  email: text("email").notNull().unique(),
  kataSandiHash: text("kata_sandi_hash").notNull(),
  peran: peranEnum("peran").notNull().default("pemilik_salon"),
  dibuatPada: timestamp("dibuat_pada", { withTimezone: true }).notNull().defaultNow(),
  diperbaruiPada: timestamp("diperbarui_pada", { withTimezone: true }).notNull().defaultNow(),
});

export const profilSalon = pgTable("profil_salon", {
  id: uuid("id").primaryKey().defaultRandom(),
  namaSalon: text("nama_salon").notNull(),
  alamat: text("alamat").notNull(),
  deskripsiSingkat: text("deskripsi_singkat"),
  jamBuka: text("jam_buka"),
  jamTutup: text("jam_tutup"),
  nomorWaSalon: text("nomor_wa_salon"),
  urlGambar: text("url_gambar"),
  diperbaruiPada: timestamp("diperbarui_pada", { withTimezone: true }).notNull().defaultNow(),
  diperbaruiOleh: uuid("diperbarui_oleh").references(() => pengguna.id),
});

export const layanan = pgTable("layanan", {
  id: uuid("id").primaryKey().defaultRandom(),
  nama: text("nama").notNull(),
  slug: text("slug").notNull().unique(),
  deskripsi: text("deskripsi"),
  hargaRupiah: integer("harga_rupiah").notNull(),
  durasiMenit: integer("durasi_menit").notNull(),
  urlGambar: text("url_gambar"),
  aktif: boolean("aktif").notNull().default(true),
  dibuatPada: timestamp("dibuat_pada", { withTimezone: true }).notNull().defaultNow(),
  diperbaruiPada: timestamp("diperbarui_pada", { withTimezone: true }).notNull().defaultNow(),
  diperbaruiOleh: uuid("diperbarui_oleh").references(() => pengguna.id),
});

export const kapster = pgTable("kapster", {
  id: uuid("id").primaryKey().defaultRandom(),
  nama: text("nama").notNull(),
  urlFoto: text("url_foto"),
  aktif: boolean("aktif").notNull().default(true),
  dibuatPada: timestamp("dibuat_pada", { withTimezone: true }).notNull().defaultNow(),
  diperbaruiPada: timestamp("diperbarui_pada", { withTimezone: true }).notNull().defaultNow(),
  diperbaruiOleh: uuid("diperbarui_oleh").references(() => pengguna.id),
});

export const jadwalKerjaKapster = pgTable("jadwal_kerja_kapster", {
  id: uuid("id").primaryKey().defaultRandom(),
  kapsterId: uuid("kapster_id").notNull().references(() => kapster.id),
  hariDalamMinggu: integer("hari_dalam_minggu").notNull(),
  jamMulai: text("jam_mulai").notNull(),
  jamSelesai: text("jam_selesai").notNull(),
  dibuatPada: timestamp("dibuat_pada", { withTimezone: true }).notNull().defaultNow(),
  diperbaruiPada: timestamp("diperbarui_pada", { withTimezone: true }).notNull().defaultNow(),
  diperbaruiOleh: uuid("diperbarui_oleh").references(() => pengguna.id),
});

export const liburKapster = pgTable("libur_kapster", {
  id: uuid("id").primaryKey().defaultRandom(),
  kapsterId: uuid("kapster_id").notNull().references(() => kapster.id),
  mulaiPada: timestamp("mulai_pada", { withTimezone: true }).notNull(),
  selesaiPada: timestamp("selesai_pada", { withTimezone: true }).notNull(),
  alasan: text("alasan"),
  dibuatPada: timestamp("dibuat_pada", { withTimezone: true }).notNull().defaultNow(),
  dibuatOleh: uuid("dibuat_oleh").references(() => pengguna.id),
});

export const booking = pgTable("booking", {
  id: uuid("id").primaryKey().defaultRandom(),
  kode: text("kode").notNull().unique(),
  userId: uuid("user_id").references(() => pengguna.id),
  namaTamu: text("nama_tamu").notNull(),
  kontakTamu: text("kontak_tamu").notNull(),
  kapsterId: uuid("kapster_id").notNull().references(() => kapster.id),
  layananId: uuid("layanan_id").notNull().references(() => layanan.id),
  namaLayananSnapshot: text("nama_layanan_snapshot").notNull(),
  hargaRupiahSnapshot: integer("harga_rupiah_snapshot").notNull(),
  durasiMenitSnapshot: integer("durasi_menit_snapshot").notNull(),
  mulaiPada: timestamp("mulai_pada", { withTimezone: true }).notNull(),
  selesaiPada: timestamp("selesai_pada", { withTimezone: true }).notNull(),
  status: statusBookingEnum("status").notNull().default("dikonfirmasi"),
  statusAktif: boolean("status_aktif").notNull().default(true),
  dibuatPada: timestamp("dibuat_pada", { withTimezone: true }).notNull().defaultNow(),
  diperbaruiPada: timestamp("diperbarui_pada", { withTimezone: true }).notNull().defaultNow(),
  diperbaruiOleh: uuid("diperbarui_oleh").references(() => pengguna.id),
});

export const pengingatWaLog = pgTable("pengingat_wa_log", {
  id: uuid("id").primaryKey().defaultRandom(),
  bookingId: uuid("booking_id").notNull().references(() => booking.id),
  dijadwalkanPada: timestamp("dijadwalkan_pada", { withTimezone: true }).notNull(),
  dikirimPada: timestamp("dikirim_pada", { withTimezone: true }),
  statusKirim: statusKirimEnum("status_kirim").notNull(),
  alasanGagal: text("alasan_gagal"),
  dibuatPada: timestamp("dibuat_pada", { withTimezone: true }).notNull().defaultNow(),
});

export const pengaturan = pgTable("pengaturan", {
  id: uuid("id").primaryKey().defaultRandom(),
  pengingatJam: integer("pengingat_jam").notNull().default(3),
  templateKonfirmasi: text("template_konfirmasi").notNull(),
  templatePengingat: text("template_pengingat").notNull(),
  templatePembatalan: text("template_pembatalan").notNull(),
  diperbaruiPada: timestamp("diperbarui_pada", { withTimezone: true }).notNull().defaultNow(),
  diperbaruiOleh: uuid("diperbarui_oleh").references(() => pengguna.id),
});

export const logAudit = pgTable("log_audit", {
  id: uuid("id").primaryKey().defaultRandom(),
  aktorId: uuid("aktor_id").references(() => pengguna.id),
  aksi: text("aksi").notNull(),
  entitas: text("entitas").notNull(),
  entitasId: uuid("entitas_id").notNull(),
  ringkasanPerubahan: text("ringkasan_perubahan").notNull(),
  dibuatPada: timestamp("dibuat_pada", { withTimezone: true }).notNull().defaultNow(),
});

database.migrasi_kustom:
CREATE EXTENSION IF NOT EXISTS btree_gist;

ALTER TABLE booking
  ADD CONSTRAINT booking_no_overlap_per_kapster
  EXCLUDE USING gist (
    kapster_id WITH =,
    tstzrange(mulai_pada, selesai_pada, '[)') WITH &&
  )
  WHERE (status_aktif = true);

CREATE UNIQUE INDEX IF NOT EXISTS booking_kode_unik_idx ON booking (kode);

ALTER TABLE booking
  ADD CONSTRAINT booking_rentang_valid CHECK (selesai_pada > mulai_pada);

ALTER TABLE libur_kapster
  ADD CONSTRAINT libur_rentang_valid CHECK (selesai_pada > mulai_pada);
